import React, { useState } from "react";
import API from "../utils/api";
import "../App.css";

function Home() {
  const [resume, setResume] = useState("");
  const [jd, setJd] = useState("");
  const [photo, setPhoto] = useState(null);
  const [template, setTemplate] = useState("modern");

  const [output, setOutput] = useState(null);
  const [score, setScore] = useState(null);
  const [loading, setLoading] = useState(false);

  // ================= OPTIMIZE =================
  const handleSubmit = async () => {
    try {
      setLoading(true);

      const formData = new FormData();
      formData.append("resumeText", resume);
      formData.append("jobDesc", jd);
      if (photo) formData.append("photo", photo);

      const res = await API.post("/resume/optimize", formData);

      setOutput(res.data.data);
      setScore(res.data.atsScore);
    } catch (err) {
      console.error(err);
      alert("Error optimizing resume");
    } finally {
      setLoading(false);
    }
  };

  // ================= DOWNLOAD =================
  const handleDownload = async () => {
    try {
      const formData = new FormData();
      formData.append("optimized", JSON.stringify(output));
      formData.append("template", template);
      if (photo) formData.append("photo", photo);

      const res = await fetch("http://localhost:5000/api/resume/download", {
        method: "POST",
        body: formData,
      });

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = "resume.pdf";
      a.click();
    } catch (err) {
      console.error(err);
      alert("Download failed");
    }
  };

  // ================= SAVE (PROTECTED) =================
  const handleSave = async () => {
    try {
      await API.post("/resume/save", {
        data: output,
        atsScore: score,
      });

      alert("Saved successfully");
    } catch (err) {
      console.error(err);
      alert("Save failed (login required)");
    }
  };

  return (
    <div className="app">
      <h1 className="title">CareerForge Pro 🚀</h1>

      <div className="main">
        {/* LEFT PANEL */}
        <div className="card">
          <h2>Input</h2>

          <div className="field">
            <label>Resume</label>
            <textarea
              placeholder="Paste your Resume..."
              value={resume}
              onChange={(e) => setResume(e.target.value)}
            />
          </div>

          <div className="field">
            <label>Job Description</label>
            <textarea
              placeholder="Paste Job Description..."
              value={jd}
              onChange={(e) => setJd(e.target.value)}
            />
          </div>

          <div className="field">
            <label>Profile Photo</label>
            <input
              type="file"
              accept="image/*"
              onChange={(e) => setPhoto(e.target.files[0])}
            />
          </div>

          {photo && (
            <img
              src={URL.createObjectURL(photo)}
              alt="preview"
              className="photo"
            />
          )}

          <div className="field">
            <label>Template</label>
            <select onChange={(e) => setTemplate(e.target.value)}>
              <option value="modern">Modern</option>
              <option value="classic">Classic</option>
              <option value="minimal">Minimal</option>
              <option value="corporate">Corporate</option>
            </select>
          </div>

          <button
            onClick={handleSubmit}
            className="primary"
            disabled={loading}
          >
            {loading ? "Generating..." : "Optimize Resume"}
          </button>
        </div>

        {/* RIGHT PANEL */}
        {output && (
          <div className="card">
            <h2>Output</h2>

            <div className="score">ATS Score: {score}%</div>

            <h3>{output.name}</h3>
            <p className="muted">
              {output.email} | {output.phone} | {output.linkedin}
            </p>

            <h4>Summary</h4>
            <p>{output.summary}</p>

            <h4>Skills</h4>
            <ul>
              {output.skills.map((s, i) => (
                <li key={i}>{s}</li>
              ))}
            </ul>

            <h4>Experience</h4>
            <ul>
              {output.experience.map((e, i) => (
                <li key={i}>{e}</li>
              ))}
            </ul>

            <h4>Keywords</h4>
            <p>{output.keywords.join(", ")}</p>

            <div className="actions">
              <button onClick={handleDownload}>Download PDF</button>
              <button onClick={handleSave}>Save</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default Home;
